function InvoiceCard({ id }) {
    return <Card title={`Invoice ${id}`} action="Pay"/>;
}

function RootLayout({ children }) {
    return (<html lang="en" className={`${geistSans.variable} ${geistMono.variable} h-full antialiased`}>
      <body className="min-h-full flex flex-col">{children}</body>
    </html>);
}

function Button({ label, onPress }) {
    return (<button type="button" onClick={onPress}>
      {label}
    </button>);
}

function PatientRow({ name }) {
    return <Row name={name} state="Waiting"/>;
}

function ShopPage() {
    const shown = useTotal([3]);
    return <Button label={`Buy ${shown}`} onPress={handleBuy}/>;
}

function OrdersPage() {
    return <ListPage title="Orders" onMore={() => console.log('Show more orders')}/>;
}

function Page({ items }) {
    return (<main data-cx-src="features/x/pages/Page.tsx:3:5" className="page">
      <h1 data-cx-src="features/x/pages/Page.tsx:4:7">Title</h1>
      <Card title="x">
        <ul data-cx-src="features/x/pages/Page.tsx:6:9">{items.map((i) => <li data-cx-src="features/x/pages/Page.tsx:6:31" key={i}>{i}</li>)}</ul>
      </Card>
      <><span data-cx-src="keep:1:1">hi</span></>
      <input data-cx-src="features/x/pages/Page.tsx:9:7" type="text"/>
    </main>);
}

function Login({ username, setUsername, password, setPassword, onSubmit, error }) {
    return (<form onSubmit={(e) => {
            e.preventDefault();
            onSubmit();
        }}>
      <label>
        Username
        <input value={username} onChange={(e) => setUsername(e.target.value)} autoComplete="username"/>
      </label>
      <label>
        Password
        <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} autoComplete="current-password"/>
      </label>
      {error && <p role="alert">{error}</p>}
      <button type="submit">Log in</button>
    </form>);
}
